async function main() {
  const out: any = [];
  const qs = [
    "Electografía España elecciones generales 26N tracking Data10 blog",
    "worldchampionship.fide.com results score Gukesh Sindarov game",
    "Destatis VPI November 2025 Indexstand Pressemitteilung",
    "gfsbern SRG Trendumfrage 29. November 2026 November",
  ];
  for (const q of qs) {
    const r = await tools.connector_web_search.web_search({ query: q, limit: 6 });
    const parsed = r as any;
    const items: any[] = [];
    const walk = (o: any) => {
      if (o && typeof o === "object") {
        if (typeof o.url === "string" && typeof o.title === "string") items.push({ url: o.url, title: o.title, desc: (o.description || "").slice(0, 200) });
        for (const k of Object.keys(o)) walk(o[k]);
      }
    };
    walk(parsed);
    out.push({ q, items: items.slice(0, 8) });
  }
  return out;
}
